\set ON_ERROR_STOP on
BEGIN;
-- Run only on the disposable local server used by the access-grant suite.
DO $$ BEGIN IF current_setting('port') <> '55443' THEN RAISE EXCEPTION 'Use disposable local port 55443'; END IF; END $$;
CREATE ROLE anon;
CREATE ROLE authenticated;
CREATE ROLE service_role;
CREATE SCHEMA auth;
CREATE TABLE auth.users(id uuid PRIMARY KEY,email text,email_confirmed_at timestamptz,active boolean DEFAULT true);
CREATE FUNCTION auth.uid() RETURNS uuid LANGUAGE sql STABLE AS $$ SELECT (nullif(current_setting('request.jwt.claims',true),'')::jsonb->>'sub')::uuid $$;
CREATE FUNCTION public.account_is_active() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER AS $$ SELECT coalesce((SELECT active FROM auth.users WHERE id=auth.uid()),false) $$;
CREATE FUNCTION public.is_super_admin(text) RETURNS boolean LANGUAGE sql STABLE AS $$ SELECT $1='super@example.test' $$;
CREATE TABLE public.calendar(id bigint PRIMARY KEY,event_name text,slug text,start_date date,end_date date,start_time time,end_time time,courts_count integer,court_labels text[],venue text,golden_point boolean,default_match_format text,is_manual boolean);
CREATE TABLE public.tournament_divisions(id uuid,event_id bigint,name text,sort_order integer,cancelled_at timestamptz);
CREATE TABLE public.event_registrations(id uuid,event_id bigint,division_id uuid,division text,full_name text,email text,partner_name text,partner_email text,status text,payment_status text,partner_payment_status text,created_at timestamptz,pay_token uuid);
CREATE TABLE public.players(id bigint,name text,email text,points integer,rankings jsonb,preferred_ranking text,active_ranking_label text,gender text,rank_label text,license_type text,paid_registration boolean,contact_number text);
CREATE TABLE public.temporary_licenses(id uuid,player_id bigint,event_id bigint,revoked_at timestamptz);
CREATE TABLE public.event_play_days(id uuid,event_id bigint,play_date date);
CREATE TABLE public.ranking_tiers(id uuid,name text);
CREATE TABLE public.ranking_points_table(id uuid,points integer);
INSERT INTO auth.users VALUES ('00000000-0000-0000-0000-000000000001','greggogoski@gmail.com',now(),true),('00000000-0000-0000-0000-000000000002','outsider@example.test',now(),true),('00000000-0000-0000-0000-000000000003','super@example.test',now(),true),('00000000-0000-0000-0000-000000000004','greggogoski@gmail.com',NULL,true);
INSERT INTO calendar(id,event_name,is_manual) VALUES (1,'Weekend',true),(2,'Other event',true),(3,'External event',false);
INSERT INTO tournament_divisions(id,event_id,name) VALUES ('10000000-0000-0000-0000-000000000001',1,'Open');
INSERT INTO event_registrations(id,event_id,full_name,email,pay_token) VALUES ('20000000-0000-0000-0000-000000000001',1,'Entrant','one@example.test','30000000-0000-0000-0000-000000000001'),('20000000-0000-0000-0000-000000000002',2,'Other entrant','other@example.test',NULL);
INSERT INTO players(id,name,email,points,contact_number) VALUES (1,'Entrant','ONE@example.test',100,'private-phone'),(2,'Other entrant','other@example.test',200,'other-phone');
\ir ../supabase/migrations/20261106115035_private_draw_rehearsal.sql
CREATE FUNCTION pg_temp.expect(ok boolean,label text) RETURNS void LANGUAGE plpgsql AS $$ BEGIN IF ok IS DISTINCT FROM true THEN RAISE EXCEPTION 'Failed: %',label; END IF; END $$;
SELECT pg_temp.expect(NOT has_function_privilege('anon','public.private_draw_rehearsal_snapshot(bigint)','execute'),'anonymous snapshot denied');
SELECT pg_temp.expect(NOT has_function_privilege('anon','public.list_private_draw_rehearsal_events()','execute'),'anonymous event list denied');
GRANT USAGE ON SCHEMA auth TO authenticated;
SET LOCAL ROLE authenticated;
SELECT set_config('request.jwt.claims','{"sub":"00000000-0000-0000-0000-000000000001","email":"greggogoski@gmail.com","role":"authenticated"}',true);
SELECT pg_temp.expect(public.can_start_private_draw_rehearsal(),'Gregg authorised');
SELECT pg_temp.expect(jsonb_array_length(public.list_private_draw_rehearsal_events())=1,'list limited to native events with divisions');
SELECT pg_temp.expect(jsonb_array_length(public.private_draw_rehearsal_snapshot(1)->'registrations')=1,'event-scoped entrants');
SELECT pg_temp.expect(jsonb_array_length(public.private_draw_rehearsal_snapshot(1)->'players')=1,'only entrant profiles');
SELECT pg_temp.expect(NOT (public.private_draw_rehearsal_snapshot(1)->'registrations'->0 ? 'pay_token'),'no payment tokens');
SELECT pg_temp.expect(NOT (public.private_draw_rehearsal_snapshot(1)->'players'->0 ? 'contact_number'),'no phone numbers');
SELECT set_config('request.jwt.claims','{"sub":"00000000-0000-0000-0000-000000000002","email":"greggogoski@gmail.com","role":"authenticated"}',true);
SELECT pg_temp.expect(NOT public.can_start_private_draw_rehearsal(),'spoofed email cannot grant access');
DO $$ BEGIN PERFORM public.private_draw_rehearsal_snapshot(1); RAISE EXCEPTION 'outsider snapshot accepted'; EXCEPTION WHEN insufficient_privilege THEN NULL; END $$;
DO $$ BEGIN PERFORM public.list_private_draw_rehearsal_events(); RAISE EXCEPTION 'outsider list accepted'; EXCEPTION WHEN insufficient_privilege THEN NULL; END $$;
SELECT set_config('request.jwt.claims','{"sub":"00000000-0000-0000-0000-000000000003","role":"authenticated"}',true);
SELECT pg_temp.expect(public.can_start_private_draw_rehearsal(),'super admin authorised');
SELECT set_config('request.jwt.claims','{"sub":"00000000-0000-0000-0000-000000000004","role":"authenticated"}',true);
SELECT pg_temp.expect(NOT public.can_start_private_draw_rehearsal(),'unconfirmed tester denied');
RESET ROLE;
UPDATE auth.users SET active=false WHERE id='00000000-0000-0000-0000-000000000001';
SELECT set_config('request.jwt.claims','{"sub":"00000000-0000-0000-0000-000000000001","role":"authenticated"}',true);
SELECT pg_temp.expect(NOT public.can_start_private_draw_rehearsal(),'inactive tester denied');
SELECT pg_temp.expect((SELECT count(*)=2 FROM event_registrations),'registrations unchanged');
SELECT pg_temp.expect((SELECT sum(points)=300 FROM players),'profile points unchanged');
ROLLBACK;
